package com.client.multichatwindows.config.ui; import net.minecraft.client.*; import net.minecraft.client.gui.*;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.network.chat.Component; public class PixelSlider extends AbstractWidget { @FunctionalInterface public interface ChangeListener{void onChange(int value);} private int value; private final int min; private final int max; private final ChangeListener listener; public PixelSlider(int x,int y,int w,int h,int min,int max,int value,ChangeListener listener){super(x,y,w,h,Component.empty());this.min=min;this.max=max;this.value=Math.max(min,Math.min(max,value));this.listener=listener;} private void updateFromMouse(double mx){double ratio=(mx-getX())/(double)Math.max(1,width);ratio=Math.max(0,Math.min(1,ratio));int nv=min+(int)Math.round(ratio*(max-min));if(nv!=value){value=nv;if(listener!=null)listener.onChange(value);}} @Override public void onClick(MouseButtonEvent click,boolean doubled){updateFromMouse(click.x());} @Override public boolean mouseDragged(MouseButtonEvent click,double offsetX,double offsetY){updateFromMouse(click.x());return true;} @Override public void extractWidgetRenderState(GuiGraphicsExtractor ctx,int mouseX,int mouseY,float delta){int cy=getY()+height/2;ctx.fill(getX(),cy-1,getX()+width,cy+1,0xFFFFFFFF);double ratio=(value-min)/(double)(max-min);int knobX=getX()+(int)Math.round(ratio*width);ctx.fill(knobX-3,getY(),knobX+3,getY()+height,0xFFFFFFFF);com.client.multichatwindows.util.GuiDrawHelper.text(ctx, Minecraft.getInstance().font,Component.literal(String.valueOf(value)),getX()+width+8,getY()+6,0xFFFFFFFF);} @Override protected void updateWidgetNarration(net.minecraft.client.gui.narration.NarrationElementOutput builder){} }
